import pprint

import six


class SummaryObjectV1(object):
    """
    SummaryObject - represents the summary field inside EmilData
    """

    openapi_types = {
        'values': 'list[str]',
        'amounts': 'list[int]',
        'totallength': 'int',
        'totalamount': 'int'
    }

    attribute_map = {
        'values': 'values',
        'amounts': 'amounts',
        'totallength': 'totallength',
        'totalamount': 'totalamount'
    }

    def __init__(self, values=None, amounts=None, totallength=None, totalamount=None):
        self._values = values
        self._amounts = amounts
        self._totallength = totallength
        self._totalamount = totalamount

    @property
    def values(self):
        return self._values

    @values.setter
    def values(self, values):
        self._values = values

    @property
    def amounts(self):
        return self._amounts

    @amounts.setter
    def amounts(self, amounts):
        self._amounts = amounts

    @property
    def totallength(self):
        return self._totallength

    @totallength.setter
    def totallength(self, totallength):
        self._totallength = totallength

    @property
    def totalamount(self):
        return self._totalamount

    @totalamount.setter
    def totalamount(self, totalamount):
        self._totalamount = totalamount

    def to_dict(self):
        result = {}
        for attr, _ in six.iteritems(self.openapi_types):
            value = getattr(self, attr)
            if value is not None:
                result[attr] = value
        return result

    def to_str(self):
        return pprint.pformat(self.to_dict())

    def __repr__(self):
        return self.to_str()

    def __eq__(self, other):
        if not isinstance(other, SummaryObjectV1):
            return False
        return self.to_dict() == other.to_dict()

    def __ne__(self, other):
        return not self.__eq__(other)
